    %cst_half = stablehlo.constant dense<5.000000e-01> : tensor<6x6x5x5xf32>
    %cst_one = stablehlo.constant dense<1.000000e+00> : tensor<6x6x5x5xf32>
    %9 = stablehlo.multiply %8, %cst_isqrt2 : tensor<6x6x5x5xf32>
