    %mean = stablehlo.divide %sum, %cnt : tensor<14x8xf32>

    // Broadcast mean to group shape
    %mean_b = stablehlo.broadcast_in_dim %mean, dims = [0, 1] : (tensor<14x8xf32>) -> tensor<14x8x2x16x16xf32>
    %diff = stablehlo.subtract %xg, %mean_b : tensor<14x8x2x16x16xf32>

    // Biased variance
    %sq = stablehlo.multiply %diff, %diff : tensor<14x8x2x16x16xf32>
    %sqsum = stablehlo.reduce(%sq init: %zero) applies stablehlo.add across dimensions = [2, 3, 4] : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>
    %var = stablehlo.divide %sqsum, %cnt : tensor<14x8xf32>

    // rsqrt(var + eps)
    %eps_b = stablehlo.broadcast_in_dim %eps, dims = [] : (tensor<f32>) -> tensor<14x8xf32>
    %var_eps = stablehlo.add %var, %eps_b : tensor<14x8xf32>
    %rstd = stablehlo.rsqrt %var_eps : tensor<14x8xf32>
    %rstd_b = stablehlo.broadcast_in_dim %rstd, dims = [0, 1] : (tensor<14x8xf32>) -> tensor<14x8x2x16x16xf32>

    // Normalize and reshape back to (14,16,16,16)
    %norm_g = stablehlo.multiply %diff, %rstd_b : tensor<14x8x2x16x16xf32>
    %norm = stablehlo.reshape %norm_g : (tensor<14x8x2x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Per-channel affine: weight/bias over channel dim 1
    %w_b = stablehlo.broadcast_in_dim %arg0, dims = [1] : (tensor<16xf32>) -> tensor<14x16x16x16xf32>
    %b_b = stablehlo.broadcast_in_dim %arg1, dims = [1] : (tensor<16xf32>) -> tensor<14x16x16x16xf32>
    %scaled = stablehlo.multiply %norm, %w_b : tensor<14x16x16x16xf32>
